#include "stdlib/blas/ext/base/ndarray/caxpb.h"
#include "stdlib/blas/ext/base/caxpb.h"
#include "stdlib/complex/float32/ctor.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"

/**
* Multiplies each element in a one-dimensional single-precision complex floating-point ndarray by a scalar constant and adds a scalar constant to each result.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray containing the scalar constant to multiply.
*     -   a zero-dimensional ndarray containing the scalar constant to add.
*
* @param arrays    list containing ndarrays
*/
void stdlib_blas_ext_caxpb( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];

	stdlib_complex64_t alpha;
	stdlib_complex64_t beta;
	stdlib_ndarray_get_complex64( arrays[ 1 ], NULL, &alpha );
	stdlib_ndarray_get_complex64( arrays[ 2 ], NULL, &beta );

	const CBLAS_INT N = stdlib_ndarray_dimension( x, 0 );
	const CBLAS_INT strideX = stdlib_ndarray_stride_elements( x, 0 );
	const CBLAS_INT offsetX = stdlib_ndarray_offset_elements( x );

	stdlib_complex64_t *dataX = (stdlib_complex64_t *)stdlib_ndarray_data( x );
	API_SUFFIX(stdlib_strided_caxpb_ndarray)( N, alpha, beta, dataX, strideX, offsetX );
}
